-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Außerordentliche Kündigung (§ 22 Abs. 2 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb einen Fachinformatiker außerordentlich kündigen, wenn er wiederholt Betriebsgeheimnisse verrät?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies bei wichtigem Grund"}, {"text": "Nein", "correct": false, "because": "Schwere Pflichtverletzung rechtfertigt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine außerordentliche Kündigung eines Fachinformatikers schriftlich erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker fristlos kündigen, wenn der Betrieb wiederholt keine Vergütung zahlt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies bei wichtigem Grund"}, {"text": "Nein", "correct": false, "because": "Pflichtverletzung des Betriebs rechtfertigt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf eine außerordentliche Kündigung eines Fachinformatikers ohne wichtigen Grund erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt einen wichtigen Grund"}, {"text": "Ja", "correct": false, "because": "Wichtiger Grund ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine außerordentliche Kündigung eines Fachinformatikers sofort wirksam sein?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG sieht fristlose Kündigung vor"}, {"text": "Nein", "correct": false, "because": "Fristlosigkeit ist charakteristisch"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt die außerordentliche Kündigung eines Fachinformatikers?', 2, '[{"text": "§ 22 Abs. 2 BBiG", "correct": true, "because": "Definiert die außerordentliche Kündigung"}, {"text": "§ 15 BBiG", "correct": false, "because": "Bezieht sich auf Berufsschule"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist eine Voraussetzung für die außerordentliche Kündigung eines Fachinformatikers?', 3, '[{"text": "Ein wichtiger Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Eine Kündigungsfrist von 4 Wochen", "correct": false, "because": "Fristlosigkeit gilt"}, {"text": "Nur eine Abmahnung", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund rechtfertigt eine außerordentliche Kündigung eines Fachinformatikers durch den Betrieb?', 3, '[{"text": "Diebstahl von Betriebseigentum", "correct": true, "because": "Schwere Pflichtverletzung gemäß § 22 Abs. 2 BBiG"}, {"text": "Einmalige Verspätung", "correct": false, "because": "Nicht ausreichend schwerwiegend"}, {"text": "Unzufriedenheit des Ausbilders", "correct": false, "because": "Kein wichtiger Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann eine außerordentliche Kündigung eines Fachinformatikers aussprechen?', 2, '[{"text": "Sowohl Betrieb als auch Auszubildender", "correct": true, "because": "§ 22 Abs. 2 BBiG gilt für beide"}, {"text": "Nur der Betrieb", "correct": false, "because": "Auszubildender darf auch kündigen"}, {"text": "Die IHK", "correct": false, "because": "IHK hat keine Kündigungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei einer außerordentlichen Kündigung eines Fachinformatikers angeben?', 3, '[{"text": "Einen wichtigen Grund in Schriftform", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform und Begründung"}, {"text": "Nur eine mündliche Begründung", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Keine Begründung", "correct": false, "because": "Grund ist zwingend"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen müssen für eine außerordentliche Kündigung eines Fachinformatikers erfüllt sein?', 4, '[{"text": "Wichtiger Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "Schriftform", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Frist von 4 Wochen", "correct": false, "because": "Fristlosigkeit gilt"}, {"text": "Unverzügliche Ausübung", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt schnelles Handeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe können eine außerordentliche Kündigung eines Fachinformatikers rechtfertigen?', 3, '[{"text": "Wiederholtes Schwänzen der Berufsschule", "correct": true, "because": "Schwere Pflichtverletzung"}, {"text": "Diebstahl von Betriebsmitteln", "correct": true, "because": "Wichtiger Grund gemäß § 22 Abs. 2"}, {"text": "Einmalige Unpünktlichkeit", "correct": false, "because": "Nicht schwerwiegend genug"}, {"text": "Verletzung der Verschwiegenheit", "correct": true, "because": "Schwere Pflichtverletzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei einer außerordentlichen Kündigung eines Fachinformatikers beachten?', 4, '[{"text": "Schriftliche Kündigung", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Schriftform"}, {"text": "Wichtigen Grund angeben", "correct": true, "because": "Voraussetzung für außerordentliche Kündigung"}, {"text": "Frist von 2 Wochen", "correct": false, "because": "Fristlosigkeit gilt"}, {"text": "Unverzüglich handeln", "correct": true, "because": "Zeitnahe Kündigung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Fachinformatiker bei einer außerordentlichen Kündigung?', 3, '[{"text": "Schriftliche Begründung verlangen", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "Kündigungsschutzklage einreichen", "correct": true, "because": "Bei unrechtmäßiger Kündigung möglich"}, {"text": "Sofortige Wiedereinstellung", "correct": false, "because": "Kein automatisches Recht"}, {"text": "Fristgerechte Kündigung erwarten", "correct": false, "because": "Fristlosigkeit gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen kann eine außerordentliche Kündigung eines Fachinformatikers erfolgen?', 3, '[{"text": "Schwere Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies"}, {"text": "Betriebsstilllegung", "correct": true, "because": "Wichtiger Grund"}, {"text": "Leichte Verstöße", "correct": false, "because": "Nicht ausreichend"}, {"text": "Gewalt gegen Kollegen", "correct": true, "because": "Schwere Verletzung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine außerordentliche Kündigung eines Fachinformatikers erfordert einen wichtigen Grund. b) Sie kann mündlich erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtiger Grund nötig, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Betrieb kann einen Fachinformatiker fristlos kündigen bei schwerem Diebstahl. b) Eine außerordentliche Kündigung muss eine Frist von 4 Wochen einhalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Diebstahl ist Grund, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann bei Nichtzahlung der Vergütung fristlos kündigen. b) Eine außerordentliche Kündigung ist in der Probezeit nicht möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nichtzahlung ist Grund, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine außerordentliche Kündigung muss schriftlich erfolgen. b) Ein wichtiger Grund ist nach der Probezeit optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Betrieb kann einen Fachinformatiker bei Gewalt fristlos kündigen. b) Eine außerordentliche Kündigung erfordert keine Begründung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewalt ist Grund, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

